        const up = ts.map((t) => eurSide(t, 1));
        const down = ts.slice().reverse().map((t) => eurSide(t, -1));
        return `${smooth(up)} A2.2 2.2 0 0 0 ${ptp(down[0])} ${smooth(down, 'L')} Z`;
