    /** The surroundings that feed a city. */
    const UMLAND_DISC = discOffsets((d2) => d2 <= SE.CITY_UMLAND * SE.CITY_UMLAND, SE.CITY_UMLAND);
    /** Tile at an offset, x wrapping; -1 beyond a pole. */
    function tileAt(i, dx, dy) {
        const y = Math.floor(i / SE.GRID_W) + dy;
        if (y < 0 || y >= SE.GRID_H)
            return -1;
        return y * SE.GRID_W + SE.wrapX((i % SE.GRID_W) + dx);
    }
