        tag: rgb('#4fd6e0'),
        waveNear: rgb('#4fd6e0'),
        waveFar: rgb('#174f5c'),
        ringFront: rgb('#4fd6e0'),
        ringBack: rgb('#1a5868'),
        spark: rgb('#dffcff'),
        air: rgb('#9ff6ff'),
        halo: rgb('#16495a'),
        ocean: ['#03101a', '#0c2c47', '#165a7a', '#2a88a2'].map(rgb),
        shelf: ['#05202a', '#14505e', '#2c8a98', '#5cc4c8'].map(rgb),
        land: ['#0c2414', '#2f6b36', '#4f9a4a', '#8ad16f'].map(rgb),
        hill: ['#1d1710', '#6f5438', '#a5874f', '#e0c68e'].map(rgb),
